targets.query:
// Stratification by thermal zone, banded on daily PEAK outdoor temperature.
// Split-level house: "over garage" (Office, Theater) takes roof/solar gain and is a
// different problem from "upper" (bedrooms above the main level). Pooling them, as the
// old four-room "upstairs" did, averaged two unrelated mechanisms. Server is excluded
// (equipment heat); Puzzle/Storage are excluded (fed by the HVAC but kept behind closed
// doors, so they are over-conditioned and not representative of the main level). The
// Office also carries an intermittent 3D-printer load.
//
// PERFORMANCE: each helper opens its own from()|>range()|>filter(). Hoisting the shared
// prefix into one `src` variable defeats filter pushdown and makes every branch scan the
// whole bucket - 185ms becomes 32s, past Grafana's 30s timeout. See the A/B panel.
//
// Peak comes from the daily summary, which is already a LOCAL calendar day and so bands
// identically to the balance-point and cooling-load panels.
LOC = {zone: "America/Chicago", offset: 0s}
rooms = (re) => from(bucket: "beestat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "runtime_sensor" and r._field == "temperature")
  |> filter(fn: (r) => r.sensor_name =~ re)
  |> group()
  |> aggregateWindow(every: 1d, fn: mean, createEmpty: false, timeSrc: "_start", location: LOC)
  |> group() |> keep(columns: ["_time", "_value"])
peak = from(bucket: "beestat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "runtime_thermostat_summary"
        and r._field == "max_outdoor_temperature")
  |> group() |> keep(columns: ["_time", "_value"]) |> rename(columns: {_value: "peak"})
garage = rooms(re: /^(Office|Theater)$/) |> rename(columns: {_value: "garage"})
upper  = rooms(re: /^(Master Bedroom|Upstairs Guest Room)$/) |> rename(columns: {_value: "upper"})
main   = rooms(re: /^(Kitchen Ecobee|Living Room|Family Room|Downstairs Guest Room)$/)
  |> rename(columns: {_value: "main"})
j1 = join(tables: {a: peak, b: garage}, on: ["_time"])
j2 = join(tables: {c: j1, d: upper}, on: ["_time"])
join(tables: {e: j2, f: main}, on: ["_time"])
  |> map(fn: (r) => ({band: float(v: int(v: (r.peak + 100.0) / 5.0)) * 5.0 - 100.0,
        g: r.garage - r.main, u: r.upper - r.main}))
  |> group(columns: ["band"])
  |> reduce(identity: {g: 0.0, u: 0.0, n: 0.0}, fn: (r, accumulator) => ({
        g: accumulator.g + r.g, u: accumulator.u + r.u, n: accumulator.n + 1.0}))
  |> filter(fn: (r) => r.n >= 3.0)
  |> map(fn: (r) => ({outdoor_f: r.band, over_garage_f: r.g / r.n, upper_f: r.u / r.n, days: r.n}))
  |> group() |> sort(columns: ["outdoor_f"])

// Fan A/B at matched outdoor conditions.
// Arms are derived from the DATA (measured blower duty), not from a hardcoded list of
// dates, so the panel keeps working after the next fan-mode change. The 80-95% duty
// band is deliberately DROPPED: those days are a mixture and would smear the contrast.
//
// PERFORMANCE, and it is not cosmetic: every helper opens its OWN from()|>range()
// |>filter() chain. Hoisting the shared prefix into `src = from(...) |> range(...)` and
// filtering per branch reads better but DEFEATS FILTER PUSHDOWN - each branch then scans
// the whole bucket for the range instead of just its own measurement. That took this
// query from 185ms to 32s, past Grafana's 30s datasource timeout, and the panel rendered
// as a red error triangle with no hint as to why.
//
// Daily peak and blower duty come from runtime_thermostat_summary rather than being
// re-derived from 5-minute data, which also makes this band on the same LOCAL calendar
// day as the balance-point and cooling-load panels. Verified the summary and a
// location-aware aggregateWindow agree exactly across the DST boundary (both stamp
// 06:00Z in CST and 05:00Z in CDT, with identical values), so the join key is safe.
LOC = {zone: "America/Chicago", offset: 0s}
summary = (fld) => from(bucket: "beestat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "runtime_thermostat_summary" and r._field == fld)
  |> group() |> keep(columns: ["_time", "_value"])
rooms = (re) => from(bucket: "beestat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "runtime_sensor" and r._field == "temperature")
  |> filter(fn: (r) => r.sensor_name =~ re)
  |> group()
  |> aggregateWindow(every: 1d, fn: mean, createEmpty: false, timeSrc: "_start", location: LOC)
  |> group() |> keep(columns: ["_time", "_value"])
peak = summary(fld: "max_outdoor_temperature") |> rename(columns: {_value: "peak"})
duty = summary(fld: "sum_fan") |> map(fn: (r) => ({_time: r._time, duty: r._value / 86400.0}))
up   = rooms(re: /^(Master Bedroom|Upstairs Guest Room)$/) |> rename(columns: {_value: "up"})
main = rooms(re: /^(Kitchen Ecobee|Living Room|Family Room|Downstairs Guest Room)$/)
  |> rename(columns: {_value: "main"})
j1 = join(tables: {a: peak, b: duty}, on: ["_time"])
j2 = join(tables: {c: j1, d: up}, on: ["_time"])
join(tables: {e: j2, f: main}, on: ["_time"])
  |> map(fn: (r) => ({
        band: float(v: int(v: (r.peak + 100.0) / 5.0)) * 5.0 - 100.0,
        gap: r.up - r.main,
        c: if r.duty >= 0.95 then 1.0 else 0.0,
        y: if r.duty < 0.80 then 1.0 else 0.0}))
  |> group(columns: ["band"])
  |> reduce(identity: {sc: 0.0, nc: 0.0, sy: 0.0, ny: 0.0}, fn: (r, accumulator) => ({
        sc: accumulator.sc + r.gap * r.c, nc: accumulator.nc + r.c,
        sy: accumulator.sy + r.gap * r.y, ny: accumulator.ny + r.y}))
  |> filter(fn: (r) => r.nc >= 3.0 and r.ny >= 3.0)
  |> map(fn: (r) => ({outdoor_f: r.band,
        cycling_f: r.sy / r.ny, continuous_f: r.sc / r.nc,
        days: r.ny + r.nc}))
  |> group() |> sort(columns: ["outdoor_f"])

// What circulation costs. Blower draw was MEASURED, not assumed: regressing the
// "19 - Furnace" circuit against this thermostat's blower duty over 814 hours gives
// 486 W attributable to the blower on top of a 55 W circuit floor (se 9 W). Electricity
// is the blended $0.1177/kWh marginal rate under monthly net metering.
// "Fan only" = blower seconds with no heating or cooling call, clamped at zero because
// aux and compressor stages can overlap within a 5-minute interval and would otherwise
// subtract twice.
from(bucket: "beestat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "runtime_thermostat_summary")
  |> filter(fn: (r) => r._field == "sum_fan" or r._field == "sum_compressor_cool_1"
        or r._field == "sum_compressor_heat_1" or r._field == "sum_auxiliary_heat_1")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({_time: r._time, s: r.sum_fan - r.sum_compressor_cool_1
        - r.sum_compressor_heat_1 - r.sum_auxiliary_heat_1}))
  |> map(fn: (r) => ({_time: r._time,
        _value: (if r.s > 0.0 then r.s else 0.0) / 3600.0 * 0.486 * 0.1177}))
  |> group() |> rename(columns: {_value: "Circulation cost"})
